10	  SettingsSchema,
11	  SettingsType,
12	  SettingsValue,
13	} from '../config/settingsSchema.js';
14	import { getSettingsSchema } from '../config/settingsSchema.js';
15	import type { Config } from '@google/gemini-cli-core';
16	import { ExperimentFlags } from '@google/gemini-cli-core';
17	
18	// The schema is now nested, but many parts of the UI and logic work better
19	// with a flattened structure and dot-notation keys. This section flattens the
20	// schema into a map for easier lookups.
21	
22	type FlattenedSchema = Record<string, SettingDefinition & { key: string }>;
23	
24	function flattenSchema(schema: SettingsSchema, prefix = ''): FlattenedSchema {
25	  let result: FlattenedSchema = {};
26	  for (const key in schema) {
27	    const newKey = prefix ? `${prefix}.${key}` : key;
28	    const definition = schema[key];
29	    result[newKey] = { ...definition, key: newKey };
30	    if (definition.properties) {
31	      result = { ...result, ...flattenSchema(definition.properties, newKey) };
32	    }
33	  }
34	  return result;
35	}
36	
37	let _FLATTENED_SCHEMA: FlattenedSchema | undefined;
38	
39	/** Returns a flattened schema, the first call is memoized for future requests. */
40	export function getFlattenedSchema() {
41	  return (
42	    _FLATTENED_SCHEMA ??
43	    (_FLATTENED_SCHEMA = flattenSchema(getSettingsSchema()))
44	  );
45	}
46	
47	function clearFlattenedSchema() {
48	  _FLATTENED_SCHEMA = undefined;
49	}
50	
51	export function getSettingsByCategory(): Record<
52	  string,
53	  Array<SettingDefinition & { key: string }>
54	> {
55	  const categories: Record<
56	    string,
57	    Array<SettingDefinition & { key: string }>
58	  > = {};
59	
60	  Object.values(getFlattenedSchema()).forEach((definition) => {
61	    const category = definition.category;
62	    if (!categories[category]) {
63	      categories[category] = [];
64	    }
65	    categories[category].push(definition);
66	  });
67	
68	  return categories;
69	}
