71	export function getSettingDefinition(
72	  key: string,
73	): (SettingDefinition & { key: string }) | undefined {
74	  return getFlattenedSchema()[key];
75	}
76	
77	export function requiresRestart(key: string): boolean {
78	  return getFlattenedSchema()[key]?.requiresRestart ?? false;
79	}
80	
81	export function getDefaultValue(key: string): SettingsValue {
82	  return getFlattenedSchema()[key]?.default;
83	}
84	
85	/**
86	 * Get the effective default value for a setting, checking experiment values when available.
87	 * For settings like compressionThreshold, this will return the experiment value if set,
88	 * otherwise falls back to the schema default.
89	 */
90	export function getEffectiveDefaultValue(
91	  key: string,
92	  config?: Config,
93	): SettingsValue {
94	  if (key === 'model.compressionThreshold' && config) {
95	    const experiments = config.getExperiments();
96	    const experimentValue =
97	      experiments?.flags[ExperimentFlags.CONTEXT_COMPRESSION_THRESHOLD]
98	        ?.floatValue;
99	    if (experimentValue !== undefined && experimentValue !== 0) {
100	      return experimentValue;
101	    }
102	  }
103	
104	  return getDefaultValue(key);
105	}
